#define KELLY_DECOMP_FULL_FEMENU_ENTRY
#define KELLY_DECOMP_FULL_FEMULTI_MENU
#include "KS/SRC/ks/FEMenu_shared.h"
#include "KS/SRC/ks/FEPanel_shared.h"

class SurferTrick;
class GraphicalMenuSystem;

class TrickBookFrontEnd : public FEMultiMenu {
    GraphicalMenuSystem *sys;
    SurferTrick **tricks[4];
    TextString *buttons;
    TextString *trickbook;
    FEMenu *State2[4];
    PanelQuad *arrows[2][2];
    PanelQuad *bkg;
    int arrow_counter;
    int arrow_num;
    bool wait_for_camera;

public:
    void OnLeft(int controller);

private:
    void ChangeButtonText(SurferTrick *trick);
};

void TrickBookFrontEnd::OnLeft(int c)
{
    arrows[0][1]->TurnOn(true);
    arrows[0][0]->TurnOn(false);
    arrow_num = 0;
    arrow_counter = 3;

    int high = highlighted->entry_num;
    int num = State2[high]->highlighted->entry_num;
    State2[high]->OnLeft(c);
    if(num != State2[high]->highlighted->entry_num)
        ChangeButtonText(tricks[high][State2[high]->highlighted->entry_num]);
}
